"use client";

import { useState } from "react";
import { Slider } from "@/components/ui/slider";
import {
  formatMultiplier,
  formatPercent,
  gameDayLabel,
  summarizeWinProbability,
} from "@/features/win-probability/win-probability-schema";
import { CARD_FRAME as SHARED_CARD_FRAME } from "@/lib/card-frame";
import { fontWeights } from "@/lib/font-weight";
import { typeClass } from "@/lib/type-scale";
import { cn } from "@/lib/utils";
import type {
  WinProbabilityData,
  WinProbabilityTeam,
} from "@/features/win-probability/win-probability-schema";
import type {
  CSSProperties,
  KeyboardEvent,
  MouseEvent,
  PointerEvent,
} from "react";

const TYPE_SUBTITLE = typeClass("subtitle", "default");
const TYPE_CAPTION = typeClass("caption", "default");
const TYPE_MICRO = typeClass("micro", "default");

export type WinProbabilityCardState =
  "streaming" | "loading" | "ready" | "error";

export interface WinProbabilityCardProperties {
  readonly state: WinProbabilityCardState;
  /**
  The team from the props, shown before the data arrives.
  */
  readonly team?: string;
  readonly data?: WinProbabilityData;
  readonly error?: string;
  readonly className?: string;
}

const CARD_FRAME = `${SHARED_CARD_FRAME} w-full max-w-[500px]`;

const MUTED = "text-muted-foreground";

/**
The Slider requires onChange; presses are stopped before it sees them, so this never runs.
*/
function ignoreChange() {
  // Nothing to do: the card shows a chance, it doesn't take one.
}

const MOVE_KEYS = new Set([
  "ArrowDown",
  "ArrowLeft",
  "ArrowRight",
  "ArrowUp",
  "End",
  "Home",
  "PageDown",
  "PageUp",
]);

function blockPress(event: PointerEvent<HTMLDivElement>) {
  event.preventDefault();
  event.stopPropagation();
}

function blockMoveKeys(event: KeyboardEvent<HTMLDivElement>) {
  if (!MOVE_KEYS.has(event.key)) {
    return;
  }
  event.preventDefault();
  event.stopPropagation();
}

function blockPreview(event: MouseEvent<HTMLDivElement>) {
  event.stopPropagation();
}

/**
The team's color as --team, and --team-bar for the scrubber fill (via --active on the Slider: Fluid's scrubber paints with that token). Lighter on a dark card so a black team's bar still shows.
*/
const TEAM_SHADES =
  "[--team-bar:var(--team)] dark:[--team-bar:color-mix(in_oklab,var(--team)_60%,white)]";

const LogoImage = ({
  src,
  onError,
  className,
}: {
  readonly src: string;
  readonly onError: () => void;
  readonly className: string;
}) => (
  // eslint-disable-next-line @next/next/no-img-element, react-doctor/nextjs-no-img-element, jsx-a11y/no-noninteractive-element-interactions -- next/image would force the logo host into the installer's next.config; onError swaps in the letters, it is not a user interaction
  <img
    src={src}
    alt=""
    width={40}
    height={40}
    loading="lazy"
    onError={onError}
    className={cn("size-10 object-contain", className)}
  />
);

const TeamLogo = ({ team }: { readonly team: WinProbabilityTeam }) => {
  const [failed, setFailed] = useState(false);
  if (failed || !team.logo) {
    return (
      <span
        aria-hidden
        className={cn(
          MUTED,
          TYPE_MICRO,
          "flex size-10 shrink-0 items-center justify-center"
        )}
        style={{ fontVariationSettings: fontWeights.semibold }}
      >
        {team.abbreviation}
      </span>
    );
  }
  return (
    <span aria-hidden className="flex size-10 shrink-0">
      <LogoImage
        src={team.logo}
        onError={() => setFailed(true)}
        className="dark:hidden"
      />
      <LogoImage
        src={team.logoDark ?? team.logo}
        onError={() => setFailed(true)}
        className="hidden dark:block"
      />
    </span>
  );
};

/**
The app's FluidProvider is size="compact", which would pick the other Slider engine and ignore scrubber — so size is pinned to "default". Not `disabled`: that greys the fill.
*/
const TeamRow = ({ team }: { readonly team: WinProbabilityTeam }) => (
  <li
    className={cn(TEAM_SHADES, "flex items-center gap-3")}
    style={{ "--team": team.color } as CSSProperties}
  >
    <TeamLogo team={team} />
    <div className="flex min-w-0 flex-1 flex-col gap-1.5">
      <div className="flex items-baseline justify-between gap-3">
        <p
          className={cn(TYPE_SUBTITLE, "min-w-0 truncate")}
          style={{ fontVariationSettings: fontWeights.normal }}
        >
          {team.name}
        </p>
        <p
          className={cn(
            MUTED,
            TYPE_CAPTION,
            "shrink-0 text-right tabular-nums"
          )}
          style={{ fontVariationSettings: fontWeights.normal }}
        >
          {formatMultiplier(team.probability)}
        </p>
      </div>
      <div
        onPointerDownCapture={blockPress}
        onKeyDownCapture={blockMoveKeys}
        onMouseMoveCapture={blockPreview}
      >
        <Slider
          size="default"
          variant="scrubber"
          value={team.probability}
          onChange={ignoreChange}
          min={0}
          max={100}
          formatValue={formatPercent}
          style={{ "--active": "var(--team-bar)" } as CSSProperties}
          className={cn(
            "cursor-default [&_.cursor-ew-resize]:cursor-default",
            "[&>span]:text-[length:var(--fs-subtitle,14px)] [&>span]:leading-[var(--lh-subtitle,20px)]"
          )}
        />
      </div>
    </div>
  </li>
);

const Header = ({ data }: { readonly data: WinProbabilityData }) => (
  <header
    className={cn(TYPE_CAPTION, "flex items-center justify-between gap-3")}
  >
    <p
      className="min-w-0 truncate"
      style={{ fontVariationSettings: fontWeights.normal }}
    >
      <span className="text-blue-600 dark:text-blue-400">NBA</span>
      <span className={MUTED}> · {gameDayLabel(data)}</span>
    </p>
    <p
      className={cn(MUTED, "shrink-0 tabular-nums")}
      style={{ fontVariationSettings: fontWeights.normal }}
    >
      {data.season}
    </p>
  </header>
);

const WinProbabilityError = ({
  team,
  message = "The scores service didn't respond. Try again in a moment.",
}: {
  readonly team?: string;
  readonly message?: string;
}) => (
  <div role="alert" className="flex flex-col gap-1">
    <p
      className={TYPE_SUBTITLE}
      style={{ fontVariationSettings: fontWeights.semibold }}
    >
      {team
        ? `Couldn't load the ${team} game's win probability`
        : "Couldn't load the win probability"}
    </p>
    <p
      className={cn(MUTED, TYPE_CAPTION)}
      style={{ fontVariationSettings: fontWeights.normal }}
    >
      {message}
    </p>
  </div>
);

const Bar = ({ className }: { readonly className?: string }) => (
  <div className={cn("bg-muted animate-pulse rounded", className)} />
);

const SKELETON_ROWS = ["away", "home"] as const;

/**
The card while its data is on the way: the same header and two rows, so nothing moves when the chances land. Shows the team as soon as it's known (with "…" while the model is still writing it).
*/
export const WinProbabilityCardSkeleton = ({
  team,
  streaming = false,
  className,
}: {
  readonly team?: string;
  readonly streaming?: boolean;
  readonly className?: string;
}) => (
  <output className={cn(CARD_FRAME, "block", className)}>
    <span className="sr-only">
      {team
        ? `Loading the ${team} game's win probability`
        : "Loading a win probability"}
    </span>
    <div aria-hidden className="flex flex-col gap-4">
      <div className="flex h-5 items-center justify-between">
        <Bar className="h-3.5 w-28" />
        <Bar className="h-3.5 w-14" />
      </div>
      {SKELETON_ROWS.map((side, index) => (
        <div key={side} className="flex items-center gap-3">
          <Bar className="size-10 rounded-full" />
          <div className="flex min-w-0 flex-1 flex-col gap-1.5">
            <div className="flex items-center justify-between gap-3">
              {index === 0 && team ? (
                <p
                  className={cn(TYPE_SUBTITLE, "min-w-0 truncate")}
                  style={{ fontVariationSettings: fontWeights.normal }}
                >
                  {team}
                  {streaming ? <span className={MUTED}>…</span> : null}
                </p>
              ) : (
                <Bar className="h-5 w-36" />
              )}
              <Bar className="h-3.5 w-9 shrink-0" />
            </div>
            <Bar className="h-8 w-full rounded-md" />
          </div>
        </div>
      ))}
    </div>
  </output>
);

export default function WinProbabilityCard({
  state,
  team,
  data,
  error,
  className,
}: WinProbabilityCardProperties) {
  if (state === "ready" && data) {
    return (
      <section
        aria-label={summarizeWinProbability(data)}
        className={cn(CARD_FRAME, "flex flex-col gap-4", className)}
      >
        <Header data={data} />
        <ul className="flex flex-col gap-4">
          {data.teams.map((side) => (
            <TeamRow key={side.abbreviation} team={side} />
          ))}
        </ul>
      </section>
    );
  }
  if (state === "error") {
    return (
      <div className={cn(CARD_FRAME, className)}>
        <WinProbabilityError team={team} message={error} />
      </div>
    );
  }
  return (
    <WinProbabilityCardSkeleton
      team={team}
      streaming={state === "streaming"}
      className={className}
    />
  );
}

"use client";

import { useEffect, useState } from "react";
import WinProbabilityCard from "@/features/win-probability/components/win-probability-card";
import {
  isPrimedWinProbability,
  loadWinProbability,
} from "@/features/win-probability/win-probability-requests";
import { errorMessage } from "@/features/win-probability/win-probability-schema";
import type { WinProbabilityData } from "@/features/win-probability/win-probability-schema";

const POLL_MS = 30_000;

function nextPoll(count: number) {
  return count + 1;
}

type Result =
  | {
      key: string;
      status: "ready";
      data: WinProbabilityData;
      isSaved: boolean;
    }
  | { key: string; status: "error"; message: string };

export default function LiveWinProbabilityCard({
  team,
  date = null,
  streaming = false,
  className,
}: {
  readonly team?: string;
  readonly date?: string | null;
  /**
  The model is still writing the card's props.
  */
  readonly streaming?: boolean;
  readonly className?: string;
}) {
  const [result, setResult] = useState<Result | null>(null);
  const [poll, setPoll] = useState(0);
  const key = `${team}:${date}`;

  useEffect(() => {
    let isCancelled = false;
    let pollTimer: ReturnType<typeof setTimeout> | undefined;
    const run = async (name: string) => {
      let next: Result;
      try {
        next = {
          data: await loadWinProbability({ date, team: name }),
          isSaved: isPrimedWinProbability({ date, team: name }),
          key,
          status: "ready",
        };
      } catch (error) {
        next = {
          key,
          message: errorMessage(error, "Win probability lookup failed."),
          status: "error",
        };
      }
      if (isCancelled) {
        return;
      }
      setResult(next);
      const isLive =
        next.status === "ready" && next.data.state === "in" && !next.isSaved;
      if (isLive) {
        pollTimer = setTimeout(() => setPoll(nextPoll), POLL_MS);
      }
    };
    if (!streaming && team) {
      run(team);
    }
    return () => {
      isCancelled = true;
      clearTimeout(pollTimer);
    };
  }, [team, date, key, streaming, poll]);

  if (streaming || !team) {
    return (
      <WinProbabilityCard state="streaming" team={team} className={className} />
    );
  }
  const current = result?.key === key ? result : null;
  if (current?.status === "ready") {
    return (
      <WinProbabilityCard
        state="ready"
        data={current.data}
        className={className}
      />
    );
  }
  if (current?.status === "error") {
    return (
      <WinProbabilityCard
        state="error"
        team={team}
        error={current.message}
        className={className}
      />
    );
  }
  return (
    <WinProbabilityCard state="loading" team={team} className={className} />
  );
}

import { z } from "zod";

export const winProbabilityCatalogEntry = {
  description:
    "Each team's chance of winning one NBA game, in one card: both teams with their logos, a bar in each team's color showing its chance (the percent in the bar), and what a win would pay back (1.9x for 53%). Before the game it shows ESPN's prediction, during the game the live chance, which it keeps current, and after it the result. Use it whenever the user asks who will win an NBA game, a team's odds or chances of winning, or the win probability of a game. Send the full name of one of the two teams. When the user names a day (\"tonight\", \"on Tuesday\", \"October 20\"), set date to that day as YYYY-MM-DD, worked out from today's date; otherwise date is null and the card shows today's game, or the one closest to now.",
  props: z.object({
    date: z
      .string()
      .nullable()
      .describe(
        'The game\'s date as YYYY-MM-DD, worked out from today\'s date whenever the user names a day ("tonight", "on Tuesday", "October 20"). Null when they name no day: the card shows the team\'s current game, today\'s or the closest one to now.'
      ),
    team: z
      .string()
      .describe(
        'One of the two teams\' full names, e.g. "New York Knicks". Either team finds the game.'
      ),
  }),
};

import { listOf } from "@/features/chat/lookup";
import { loadWinProbability } from "@/features/win-probability/win-probability-requests";
import { normalizeTeam } from "@/features/win-probability/win-probability-schema";
import type { CardLookup } from "@/features/chat/lookup";

function propertiesOf(properties: Record<string, unknown>) {
  return {
    date: typeof properties.date === "string" ? properties.date : null,
    team: typeof properties.team === "string" ? properties.team : "",
  };
}

export const winProbabilityLookup: CardLookup = {
  intent: (teams) =>
    teams.length === 1
      ? `The ${teams[0]} game's win probability`
      : `Win probability for the ${listOf(teams)} games`,
  load: (properties) => loadWinProbability(propertiesOf(properties)),
  sources: () => [
    {
      href: "https://www.espn.com/nba/scoreboard",
      label: "espn.com/nba/scoreboard",
    },
  ],
  subject: (properties) => normalizeTeam(propertiesOf(properties).team),
};

import { normalizeTeam } from "@/features/win-probability/win-probability-schema";
import type { WinProbabilityData } from "@/features/win-probability/win-probability-schema";

const sharedWinProbabilityRequests = new Map<
  string,
  { expiresAt: number; chances: Promise<WinProbabilityData> }
>();
const REUSE_MS = 20_000;

/**
Which game a card asks for.
*/
export interface WinProbabilityRequest {
  readonly team: string;
  readonly date?: string | null;
}

function requestKey(request: WinProbabilityRequest) {
  const name = (normalizeTeam(request.team) ?? request.team).toLowerCase();
  return `${name}:${request.date ?? "current"}`;
}

async function fetchWinProbability({ team, date }: WinProbabilityRequest) {
  const parameters = new URLSearchParams({ team });
  if (date) {
    parameters.set("date", date);
  }
  const response = await fetch(`/api/win-probability?${parameters}`);
  const body = (await response.json()) as
    WinProbabilityData | { error: string };
  if (!response.ok || "error" in body) {
    throw new Error(
      "error" in body
        ? body.error
        : `Win probability request failed: ${response.status}`
    );
  }
  return body;
}

async function requestWinProbability(
  key: string,
  request: WinProbabilityRequest
) {
  try {
    return await fetchWinProbability(request);
  } catch (error) {
    sharedWinProbabilityRequests.delete(key);
    throw error;
  }
}

export function loadWinProbability(request: WinProbabilityRequest) {
  const key = requestKey(request);
  const hit = sharedWinProbabilityRequests.get(key);
  if (hit && Date.now() < hit.expiresAt) {
    return hit.chances;
  }
  const chances = requestWinProbability(key, request);
  sharedWinProbabilityRequests.set(key, {
    chances,
    expiresAt: Date.now() + REUSE_MS,
  });
  return chances;
}

export function primeWinProbability(
  request: WinProbabilityRequest,
  data: WinProbabilityData
) {
  sharedWinProbabilityRequests.set(requestKey(request), {
    chances: Promise.resolve(data),
    expiresAt: Infinity,
  });
}

/**
True while the saved chances for these props are a recording's, which never go stale: the card doesn't poll them.
*/
export function isPrimedWinProbability(request: WinProbabilityRequest) {
  return (
    sharedWinProbabilityRequests.get(requestKey(request))?.expiresAt ===
    Infinity
  );
}

import "server-only";
import { findGame } from "@/features/scoreboard/scoreboard-queries";
import type {
  EspnCompetitor,
  EspnEvent,
} from "@/features/scoreboard/scoreboard-queries";
import type {
  WinProbabilityData,
  WinProbabilityTeam,
} from "@/features/win-probability/win-probability-schema";

// Server only: ESPN's site API doesn't allow browser requests (CORS).

const SUMMARY =
  "https://site.api.espn.com/apis/site/v2/sports/basketball/nba/summary";

const TIMEOUT_MS = 8000;
const NOT_FOUND = 404;
const PERCENT = 100;

/**
A game with no chances to show yet: ESPN hasn't predicted it.
*/
export class WinProbabilityNotFoundError extends Error {
  readonly status = NOT_FOUND;

  constructor(message: string, options?: ErrorOptions) {
    super(message, options);
    this.name = "WinProbabilityNotFoundError";
  }
}

interface EspnSummary {
  /**
  ESPN's Matchup Predictor, before the game: each side's chance as a string percent, "53.1".
  */
  predictor?: {
    homeTeam?: { gameProjection?: string };
    awayTeam?: { gameProjection?: string };
  };
  /**
  The home team's chance after each play, 0 to 1, oldest first. Empty before the game.
  */
  winprobability?: { homeWinPercentage: number }[];
}

function hex(color: string | undefined) {
  return color && /^[\da-f]{6}$/iu.test(color)
    ? `#${color.toLowerCase()}`
    : null;
}

function channels(color: string) {
  const value = Number.parseInt(color.slice(1), 16);
  // eslint-disable-next-line no-bitwise -- unpacks the three 8-bit channels of a hex color
  return [(value >> 16) & 255, (value >> 8) & 255, value & 255];
}

function distance(first: string, second: string) {
  const [r1, g1, b1] = channels(first);
  const [r2, g2, b2] = channels(second);
  return Math.hypot(r1 - r2, g1 - g2, b1 - b2);
}

const CLASH_DISTANCE = 60;
const WHITE = "#ffffff";
const BLACK = "#000000";
const EDGE_DISTANCE = 60;
const NEUTRAL = "#71717a";

function colorsOf(away: EspnCompetitor, home: EspnCompetitor) {
  const homeColor = hex(home.team.color) ?? NEUTRAL;
  const awayColor = hex(away.team.color) ?? NEUTRAL;
  const awayAlternate = hex(away.team.alternateColor);
  const isClash = distance(awayColor, homeColor) < CLASH_DISTANCE;
  const isUsable =
    awayAlternate !== null &&
    distance(awayAlternate, homeColor) >= CLASH_DISTANCE &&
    distance(awayAlternate, WHITE) >= EDGE_DISTANCE &&
    distance(awayAlternate, BLACK) >= EDGE_DISTANCE;
  return [isClash && isUsable ? awayAlternate : awayColor, homeColor] as const;
}

function homeChance(
  event: EspnEvent,
  summary: EspnSummary,
  home: EspnCompetitor
) {
  const { state } = event.status.type;
  if (state === "post") {
    return home.winner ? PERCENT : 0;
  }
  const latest = summary.winprobability?.at(-1)?.homeWinPercentage;
  if (state === "in" && typeof latest === "number") {
    return latest * PERCENT;
  }
  const predicted = Number(summary.predictor?.homeTeam?.gameProjection);
  if (
    Number.isNaN(predicted) ||
    summary.predictor?.homeTeam?.gameProjection === undefined
  ) {
    throw new WinProbabilityNotFoundError(
      "ESPN hasn't predicted this game yet."
    );
  }
  return predicted;
}

/**
"2027" reads "2026-27": ESPN names a season by the year it ends.
*/
function seasonName(year: number | undefined, startsAt: number) {
  const start = new Date(startsAt);
  const end = year ?? start.getUTCFullYear();
  return `${end - 1}-${String(end % PERCENT).padStart(2, "0")}`;
}

function teamOf(
  competitor: EspnCompetitor,
  color: string,
  probability: number
): WinProbabilityTeam {
  return {
    abbreviation: competitor.team.abbreviation,
    color,
    logo: competitor.team.logo ?? null,
    logoDark: competitor.team.logoDark ?? null,
    name: competitor.team.displayName,
    probability,
  };
}

/**
Each team's chance of winning one NBA team's game: with a date (YYYY-MM-DD), the game that day; without one, today's game, or the closest one to now.
*/
export async function getWinProbability(
  query: string,
  date?: string
): Promise<WinProbabilityData> {
  const event = await findGame(query, date);
  const competitors = event.competitions[0]?.competitors ?? [];
  const away = competitors.find((side) => side.homeAway === "away");
  const home = competitors.find((side) => side.homeAway === "home");
  if (!(away && home)) {
    throw new Error("The scores service sent a game without two teams.");
  }
  const response = await fetch(`${SUMMARY}?event=${event.id}`, {
    signal: AbortSignal.timeout(TIMEOUT_MS),
  });
  if (!response.ok) {
    throw new Error(`The scores service returned ${response.status}.`);
  }
  const summary = (await response.json()) as EspnSummary;
  const home100 = homeChance(event, summary, home);
  const [awayColor, homeColor] = colorsOf(away, home);
  const startsAt = Date.parse(event.date);
  return {
    asOf: Date.now(),
    season: seasonName(event.season?.year, startsAt),
    startsAt,
    state: event.status.type.state,
    teams: [
      teamOf(away, awayColor, PERCENT - home100),
      teamOf(home, homeColor, home100),
    ],
  };
}

/**
Where the game is: not started, being played, or over.
*/
export type GameState = "pre" | "in" | "post";

/**
One team's side of the game.
*/
export interface WinProbabilityTeam {
  /**
  e.g. "New York Knicks".
  */
  name: string;
  /**
  e.g. "NY".
  */
  abbreviation: string;
  /**
  The team's logo, a square PNG, and the one drawn for dark backgrounds. Null when ESPN has none.
  */
  logo: string | null;
  logoDark: string | null;
  /**
  The color its bar and percent are drawn in, as "#rrggbb". The away team takes its second color when both teams share one.
  */
  color: string;
  /**
  Its chance of winning, 0 to 100.
  */
  probability: number;
}

/**
Each team's chance of winning one NBA game.
*/
export interface WinProbabilityData {
  state: GameState;
  /**
  Unix time in milliseconds of the start.
  */
  startsAt: number;
  /**
  e.g. "2026-27".
  */
  season: string;
  /**
  Away team first, then home, as a matchup is written.
  */
  teams: [WinProbabilityTeam, WinProbabilityTeam];
  /**
  Unix time in milliseconds the chances were read.
  */
  asOf: number;
}

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/u;

/**
True for a real calendar day written as YYYY-MM-DD.
*/
export function isGameDate(date: string): boolean {
  if (!ISO_DATE.test(date)) {
    return false;
  }
  const parsed = new Date(`${date}T00:00:00Z`);
  return (
    !Number.isNaN(parsed.getTime()) && parsed.toISOString().startsWith(date)
  );
}

/**
"lakers" and " Lakers " both read "Lakers". Null when nothing is left.
*/
export function normalizeTeam(team: string): string | null {
  const trimmed = team.trim().replaceAll(/\s+/gu, " ");
  return trimmed || null;
}

/**
The message of a thrown error, or the fallback when something else was thrown. Uses instanceof rather than Error.isError, which Node 22 and older browsers don't have.
*/
export function errorMessage(error: unknown, fallback: string): string {
  // eslint-disable-next-line unicorn/prefer-error-is-error -- Error.isError is missing on Node 22 and older browsers
  return error instanceof Error ? error.message : fallback;
}

/**
A chance as a whole percent: "53%".
*/
export function formatPercent(probability: number): string {
  return `${Math.round(probability)}%`;
}

/**
What a win pays back for each unit, read from the chance: 53% pays 1.9x. A dash when the chance is 0, since nothing pays back.
*/
export function formatMultiplier(probability: number): string {
  return probability > 0 ? `${(100 / probability).toFixed(1)}x` : "–";
}

const EASTERN_DAY = new Intl.DateTimeFormat("en-CA", {
  day: "2-digit",
  month: "2-digit",
  timeZone: "America/New_York",
  year: "numeric",
});

const DAY_MS = 86_400_000;

function easternDay(time: number) {
  return Date.parse(`${EASTERN_DAY.format(time)}T00:00:00Z`);
}

/**
The game's day next to when the chances were read, the way a scoreboard says it: "Today", "Yesterday", "Tomorrow", else "Tue, Oct 20". Uses US Eastern days, ESPN's own, so the server and the browser agree.
*/
export function gameDayLabel(data: WinProbabilityData): string {
  const days = Math.round(
    (easternDay(data.startsAt) - easternDay(data.asOf)) / DAY_MS
  );
  const relative: Record<number, string> = {
    [-1]: "Yesterday",
    0: "Today",
    1: "Tomorrow",
  };
  const start = new Date(data.startsAt);
  return (
    relative[days] ??
    start.toLocaleDateString("en-US", {
      day: "numeric",
      month: "short",
      timeZone: "America/New_York",
      weekday: "short",
    })
  );
}

/**
One sentence the model (or a screen reader) can use to describe the card.
*/
export function summarizeWinProbability(data: WinProbabilityData): string {
  const [away, home] = data.teams;
  const chances = `${away.name} ${formatPercent(away.probability)}, ${home.name} ${formatPercent(home.probability)}`;
  if (data.state === "post") {
    return `${away.name} at ${home.name}, final: ${chances}.`;
  }
  return data.state === "in"
    ? `${away.name} at ${home.name}, live chance of winning: ${chances}.`
    : `${away.name} at ${home.name}, chance of winning before the game: ${chances}.`;
}

import "server-only";
import type {
  GameState,
  ScoreboardData,
  ScoreboardSeries,
  ScoreboardTeam,
} from "@/features/scoreboard/scoreboard-schema";

// Server only: ESPN's site API doesn't allow browser requests (CORS).

const NBA = "https://site.api.espn.com/apis/site/v2/sports/basketball/nba";

export interface EspnTeam {
  id: string;
  abbreviation: string;
  displayName: string;
  shortDisplayName: string;
  name?: string;
  nickname?: string;
  location?: string;
  logo?: string;
  logoDark?: string;
  /**
  The team's colors as hex without the #, e.g. "1d428a".
  */
  color?: string;
  alternateColor?: string;
}

interface EspnTeams {
  sports: { leagues: { teams: { team: EspnTeam }[] }[] }[];
}

export interface EspnStatus {
  type: { state: GameState; shortDetail: string };
}

export interface EspnCompetitor {
  homeAway: "home" | "away";
  score?: string;
  winner?: boolean;
  records?: { type?: string; summary: string }[];
  linescores?: { value: number }[];
  team: EspnTeam;
}

export interface EspnEvent {
  id: string;
  date: string;
  status: EspnStatus;
  season?: { slug?: string; year?: number };
  competitions: {
    notes?: { headline?: string }[];
    series?: {
      type?: string;
      summary?: string;
      completed?: boolean;
      totalCompetitions?: number;
      competitors?: { id: string; wins?: number }[];
    };
    venue?: { fullName?: string };
    broadcast?: string;
    broadcasts?: { names?: string[] }[];
    competitors: EspnCompetitor[];
  }[];
}

interface EspnScoreboard {
  events?: EspnEvent[];
}

interface EspnSchedule {
  events?: {
    id: string;
    date: string;
    competitions: { status: EspnStatus }[];
  }[];
}

const NOT_FOUND = 404;

/**
A lookup that found no team, or no game for it.
*/
export class ScoreboardNotFoundError extends Error {
  readonly status = NOT_FOUND;

  constructor(message: string, options?: ErrorOptions) {
    super(message, options);
    this.name = "ScoreboardNotFoundError";
  }
}

const TIMEOUT_MS = 8000;
const TEAMS_FRESH_MS = 86_400_000;
const RECENT_MS = 36 * 3_600_000;
const NOT_LETTERS = /[^\da-z]+/gu;

async function espn<T>(path: string): Promise<T> {
  const response = await fetch(`${NBA}/${path}`, {
    signal: AbortSignal.timeout(TIMEOUT_MS),
  });
  if (!response.ok) {
    throw new Error(`The scores service returned ${response.status}.`);
  }
  return (await response.json()) as T;
}

const teamList: {
  current: { expiresAt: number; teams: Promise<EspnTeam[]> } | null;
} = { current: null };

async function fetchTeams() {
  let body: EspnTeams;
  try {
    body = await espn<EspnTeams>("teams");
  } catch (error) {
    teamList.current = null;
    throw error;
  }
  return body.sports[0]?.leagues[0]?.teams.map(({ team }) => team) ?? [];
}

function nbaTeams() {
  const hit = teamList.current;
  if (hit && Date.now() < hit.expiresAt) {
    return hit.teams;
  }
  const teams = fetchTeams();
  teamList.current = { expiresAt: Date.now() + TEAMS_FRESH_MS, teams };
  return teams;
}

function simplify(text = "") {
  return text.toLowerCase().replaceAll(NOT_LETTERS, " ").trim();
}

async function findTeam(query: string) {
  const wanted = simplify(query);
  const teams = await nbaTeams();
  const names = (team: EspnTeam) =>
    [
      team.abbreviation,
      team.displayName,
      team.shortDisplayName,
      team.name,
      team.nickname,
      team.location,
    ].map(simplify);
  const team =
    teams.find((candidate) => names(candidate).includes(wanted)) ??
    teams.find((candidate) =>
      simplify(candidate.displayName).includes(wanted)
    ) ??
    teams.find((candidate) => {
      const nickname = simplify(candidate.name ?? candidate.shortDisplayName);
      return nickname !== "" && wanted.includes(nickname);
    });
  if (!team) {
    throw new ScoreboardNotFoundError(`No NBA team called "${query}".`);
  }
  return team;
}

const EASTERN_DAY = new Intl.DateTimeFormat("en-CA", {
  day: "2-digit",
  month: "2-digit",
  timeZone: "America/New_York",
  year: "numeric",
});

/**
The scoreboard day a game falls on. ESPN files games by the US Eastern date, so a 10:30 PM Pacific start is still that day's game.
*/
function scoreboardDay(time: number) {
  return EASTERN_DAY.format(time).replaceAll("-", "");
}

function teamOf(competitor: EspnCompetitor, state: GameState): ScoreboardTeam {
  const { team } = competitor;
  const score = Math.trunc(Number(competitor.score ?? NaN));
  return {
    abbreviation: team.abbreviation,
    isWinner: competitor.winner === true,
    logo: team.logo ?? null,
    logoDark: team.logoDark ?? null,
    name: team.displayName,
    periods: (competitor.linescores ?? []).map((period) => period.value),
    record:
      competitor.records?.find((record) => record.type === "total")?.summary ??
      competitor.records?.[0]?.summary ??
      null,
    score: state === "pre" || Number.isNaN(score) ? null : score,
    shortName: team.shortDisplayName,
  };
}

const PHASE_LABEL: Record<string, string> = {
  "play-in-season": "Play-In",
  "post-season": "Playoffs",
  preseason: "Preseason",
};

function stageOf(event: EspnEvent) {
  const phase = PHASE_LABEL[event.season?.slug ?? ""] ?? null;
  const note = event.competitions[0]?.notes?.[0]?.headline || null;
  if (note && event.season?.slug === "preseason") {
    return `${phase} · ${note}`;
  }
  const series = event.competitions[0]?.series;
  // ESPN can attach a later playoff series between the same two teams to a regular-season game, so only playoff games show one.
  const isPlayoffs = event.season?.slug === "post-season";
  const standing =
    isPlayoffs && series?.type === "playoff" ? series.summary : undefined;
  const label = note ?? phase;
  return label && standing ? `${label} · ${standing}` : label;
}

const FINALS_NOTE = /^NBA Finals\b/u;
const BEST_OF_SEVEN = 7;

function seriesOf(event: EspnEvent): ScoreboardSeries | null {
  const [competition] = event.competitions;
  const { series } = competition;
  if (event.season?.slug !== "post-season" || series?.type !== "playoff") {
    return null;
  }
  const winsOf = (side: "home" | "away") => {
    const id = competition.competitors.find(
      (competitor) => competitor.homeAway === side
    )?.team.id;
    return series.competitors?.find((team) => team.id === id)?.wins ?? 0;
  };
  const note = competition.notes?.[0]?.headline ?? "";
  const game = Math.trunc(Number(note.split("Game ", 2)[1] ?? NaN));
  return {
    awayWins: winsOf("away"),
    game: Number.isNaN(game) ? null : game,
    homeWins: winsOf("home"),
    isComplete: series.completed === true,
    isFinals: FINALS_NOTE.test(note),
    length: series.totalCompetitions ?? BEST_OF_SEVEN,
    summary: series.summary ?? "",
  };
}

function gameOf(event: EspnEvent): ScoreboardData {
  const [competition] = event.competitions;
  const { state, shortDetail } = event.status.type;
  const away = competition.competitors.find((side) => side.homeAway === "away");
  const home = competition.competitors.find((side) => side.homeAway === "home");
  if (!(away && home)) {
    throw new Error("The scores service sent a game without two teams.");
  }
  return {
    asOf: Date.now(),
    away: teamOf(away, state),
    broadcast:
      competition.broadcast ?? competition.broadcasts?.[0]?.names?.[0] ?? null,
    home: teamOf(home, state),
    series: seriesOf(event),
    stage: stageOf(event),
    startsAt: Date.parse(event.date),
    state,
    status: shortDetail,
    venue: competition.venue?.fullName ?? null,
  };
}

async function eventsOn(day?: string) {
  const query = day ? `?dates=${day}` : "";
  const body = await espn<EspnScoreboard>(`scoreboard${query}`);
  return body.events ?? [];
}

function playing(teamId: string) {
  return (event: EspnEvent) =>
    event.competitions[0]?.competitors.some(
      (side) => side.team.id === teamId
    ) ?? false;
}

async function pickFromSchedule(team: EspnTeam) {
  const { events = [] } = await espn<EspnSchedule>(`teams/${team.id}/schedule`);
  const games = events
    .map((event) => ({
      id: event.id,
      startsAt: Date.parse(event.date),
      state: event.competitions[0]?.status.type.state,
    }))
    .toSorted((first, second) => first.startsAt - second.startsAt);
  const live = games.find((game) => game.state === "in");
  if (live) {
    return live;
  }
  const now = Date.now();
  const last = games.findLast((game) => game.state === "post");
  const next = games.find(
    (game) => game.state === "pre" && game.startsAt > now
  );
  const isRecent = last !== undefined && now - last.startsAt < RECENT_MS;
  return isRecent ? last : (next ?? last);
}

/**
ESPN's record of one NBA team's game, found the way getScoreboard finds it: with a date (YYYY-MM-DD), the game that day; without one, today's game, or the closest one to now. Other NBA cards about one game (win probability) start from it.
*/
export async function findGame(
  query: string,
  date?: string
): Promise<EspnEvent> {
  const team = await findTeam(query);

  if (date) {
    const events = await eventsOn(date.replaceAll("-", ""));
    const event = events.find(playing(team.id));
    if (!event) {
      throw new ScoreboardNotFoundError(
        `The ${team.displayName} have no game on ${date}.`
      );
    }
    return event;
  }

  const current = await eventsOn();
  const today = current.find(playing(team.id));
  if (today) {
    return today;
  }

  const picked = await pickFromSchedule(team);
  if (!picked) {
    throw new ScoreboardNotFoundError(
      `The ${team.displayName} have no recent or upcoming games.`
    );
  }
  const events = await eventsOn(scoreboardDay(picked.startsAt));
  const event = events.find((candidate) => candidate.id === picked.id);
  if (!event) {
    throw new ScoreboardNotFoundError(
      `Couldn't find that ${team.displayName} game.`
    );
  }
  return event;
}

/**
The score of one NBA team's game. With a date (YYYY-MM-DD), the game that day; without one, today's game, or the closest one to now. Each team's points come by quarter, too.
*/
export async function getScoreboard(
  query: string,
  date?: string
): Promise<ScoreboardData> {
  return gameOf(await findGame(query, date));
}

/**
Where the game is: not started, being played, or over.
*/
export type GameState = "pre" | "in" | "post";

export interface ScoreboardTeam {
  /**
  e.g. "Los Angeles Lakers".
  */
  name: string;
  /**
  e.g. "Lakers".
  */
  shortName: string;
  /**
  e.g. "LAL".
  */
  abbreviation: string;
  /**
  The team's logo, a square PNG. Null when ESPN has none for it.
  */
  logo: string | null;
  /**
  The same logo drawn for a dark background. Null when ESPN has none.
  */
  logoDark: string | null;
  /**
  Null before the game starts.
  */
  score: number | null;
  /**
  The season record, e.g. "4-1". Null when ESPN doesn't give one.
  */
  record: string | null;
  isWinner: boolean;
  /**
  Points in each period played so far, first quarter first, overtimes after the fourth. Empty before the game; a game in progress counts its current quarter so far.
  */
  periods: number[];
}

/**
Where a playoff series stands, as of this game: before it starts, the wins so far; once it ends, the wins counting it.
*/
export interface ScoreboardSeries {
  /**
  Most games the series can last, e.g. 7.
  */
  length: number;
  awayWins: number;
  homeWins: number;
  /**
  As ESPN writes it: "NY leads series 3-1", "NY wins series 4-1".
  */
  summary: string;
  /**
  True once a team has won the series.
  */
  isComplete: boolean;
  /**
  True for the NBA Finals.
  */
  isFinals: boolean;
  /**
  Which game of the series this is, e.g. 4. Null when ESPN doesn't say.
  */
  game: number | null;
}

/**
One NBA game.
*/
export interface ScoreboardData {
  state: GameState;
  /**
  How the game stands, as ESPN writes it: "8:12 - 3rd", "Final/OT", "10/17 - 7:00 PM EDT".
  */
  status: string;
  /**
  Unix time in milliseconds of the start.
  */
  startsAt: number;
  away: ScoreboardTeam;
  home: ScoreboardTeam;
  venue: string | null;
  /**
  Which part of the season the game belongs to, or what makes it special: "Preseason", "Play-In", "NBA Cup Championship", "NBA Finals - Game 4". Null for an ordinary regular-season game.
  */
  stage: string | null;
  /**
  The playoff series this game is part of. Null outside the playoffs.
  */
  series: ScoreboardSeries | null;
  /**
  The TV channel or stream, e.g. "ESPN".
  */
  broadcast: string | null;
  /**
  Unix time in milliseconds the score was read.
  */
  asOf: number;
}

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/u;

/**
True for a real calendar day written as YYYY-MM-DD.
*/
export function isGameDate(date: string): boolean {
  if (!ISO_DATE.test(date)) {
    return false;
  }
  const parsed = new Date(`${date}T00:00:00Z`);
  return (
    !Number.isNaN(parsed.getTime()) && parsed.toISOString().startsWith(date)
  );
}

/**
"lakers" and " Lakers " both read "Lakers". Null when nothing is left.
*/
export function normalizeTeam(team: string): string | null {
  const trimmed = team.trim().replaceAll(/\s+/gu, " ");
  return trimmed || null;
}

/**
The message of a thrown error, or the fallback when something else was thrown. Uses instanceof rather than Error.isError, which Node 22 and older browsers don't have.
*/
export function errorMessage(error: unknown, fallback: string): string {
  // eslint-disable-next-line unicorn/prefer-error-is-error -- Error.isError is missing on Node 22 and older browsers
  return error instanceof Error ? error.message : fallback;
}

const REGULATION_QUARTERS = 4;

/**
The line score's column heads for the periods played: "1" to "4", then "OT", "2OT" and on.
*/
export function periodLabels(count: number): string[] {
  return Array.from({ length: count }, (_, index) => {
    const overtime = index + 1 - REGULATION_QUARTERS;
    if (overtime <= 0) {
      return String(index + 1);
    }
    return overtime === 1 ? "OT" : `${overtime}OT`;
  });
}

const EASTERN_DAY = new Intl.DateTimeFormat("en-CA", {
  day: "2-digit",
  month: "2-digit",
  timeZone: "America/New_York",
  year: "numeric",
});

const DAY_MS = 86_400_000;

function easternDay(time: number) {
  return Date.parse(`${EASTERN_DAY.format(time)}T00:00:00Z`);
}

/**
The game's day next to when the score was read, the way a scoreboard says it: "Today", "Yesterday", "Tomorrow", else "Sat, Oct 17". Uses US Eastern days, ESPN's own, so the server and the browser agree.
*/
export function gameDayLabel(data: ScoreboardData): string {
  const days = Math.round(
    (easternDay(data.startsAt) - easternDay(data.asOf)) / DAY_MS
  );
  if (days === 0) {
    return "Today";
  }
  if (days === -1) {
    return "Yesterday";
  }
  if (days === 1) {
    return "Tomorrow";
  }
  const start = new Date(data.startsAt);
  return start.toLocaleDateString("en-US", {
    day: "numeric",
    month: "short",
    timeZone: "America/New_York",
    weekday: "short",
  });
}

/**
One sentence the model (or a screen reader) can use to describe the card.
*/
export function summarizeScoreboard(data: ScoreboardData): string {
  const { away, home } = data;
  const matchup = `${away.name} at ${home.name}`;
  if (data.state === "pre") {
    return `${matchup}, ${data.status}.`;
  }
  const score = `${away.shortName} ${away.score ?? 0}, ${home.shortName} ${home.score ?? 0}`;
  return data.state === "post"
    ? `${matchup}: ${data.status}, ${score}.`
    : `${matchup}, live (${data.status}): ${score}.`;
}

/**
The surface every data card shares: the page's own background and text, and one hairline border. Cards with their own shape (a seat map, a ticket stub) take just this.
*/
export const CARD_SURFACE = "bg-background text-foreground border";

/**
The whole frame of a plain data card: the shared surface with 1rem corners and 1rem of padding. Each card adds its own width.
*/
export const CARD_FRAME = `${CARD_SURFACE} rounded-2xl p-4`;

import { ScoreboardNotFoundError } from "@/features/scoreboard/scoreboard-queries";
import {
  getWinProbability,
  WinProbabilityNotFoundError,
} from "@/features/win-probability/win-probability-queries";
import {
  errorMessage,
  isGameDate,
  normalizeTeam,
} from "@/features/win-probability/win-probability-schema";

const CACHE = "public, s-maxage=15, stale-while-revalidate=30";

const UPSTREAM_FAILED = 502;

function statusOf(error: unknown) {
  return error instanceof ScoreboardNotFoundError ||
    error instanceof WinProbabilityNotFoundError
    ? error.status
    : UPSTREAM_FAILED;
}

// eslint-disable-next-line sonarjs/function-name -- Next.js route handlers must be named after the HTTP method
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const team = normalizeTeam(searchParams.get("team") ?? "");
  const date = searchParams.get("date") ?? undefined;

  const isDateValid = date === undefined || isGameDate(date);
  if (!(team && isDateValid)) {
    return Response.json(
      {
        error:
          'Pass an NBA team such as "New York Knicks", and optionally a date as YYYY-MM-DD.',
      },
      { status: 400 }
    );
  }

  try {
    return Response.json(await getWinProbability(team, date), {
      headers: { "Cache-Control": CACHE },
    });
  } catch (error) {
    return Response.json(
      { error: errorMessage(error, "Win probability lookup failed.") },
      { status: statusOf(error) }
    );
  }
}
